// Corpus generator for differential testing. Deterministic (seeded PRNG).
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';

let _s = 0x2f6e2b1 >>> 0;
function rnd() { // mulberry32
  _s = (_s + 0x6D2B79F5) >>> 0;
  let t = _s;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
const ri = (n) => Math.floor(rnd() * n);
const pick = (a) => a[ri(a.length)];

const VALID = readFileSync('/tmp/valid3.sorted', 'utf8').trim().split('\n');
const cases = [];
const add = (argv, tag) => cases.push({ argv, tag });

// ---- A: sample-test-like ---------------------------------------------------
for (let i = 0; i < 4000; i++) {
  const whole = ri(100000);
  const frac = ri(100);
  const amt = `${whole}.${String(frac).padStart(2, '0')}`;
  add(['--amount', amt, '--currency', pick(VALID)], 'A:sample');
}

// ---- B: integers / halves / high precision ---------------------------------
for (let i = 0; i < 700; i++) {
  add(['--amount', String(ri(1000000)), '--currency', 'USD'], 'B:int');
}

}
for (let i = 0; i < 700; i++) {
  const d = 1 + ri(20);
  let s = String(ri(10) || 1);
  for (let k = 0; k < d; k++) s += String(ri(10));
  const dot = 1 + ri(s.length - 1);
  add(['--amount', s.slice(0, dot) + '.' + s.slice(dot), '--currency', 'EUR'], 'B:prec');
}
for (const v of ['0', '1', '2', '3', '7', '9', '10', '0.5', '2.5', '1.1', '2.675', '4.0', '100.0',
  '0.1', '0.2', '0.3', '1.005', '1e15', '1e16', '1e17', '1e21', '1e22', '9999999999999998',
  '99999999999999999', '999999999999999999999', '0.0001', '0.00001', '1e-5', '1e-6', '1e-7',
  '123.456789012345678', '3.0000000000000004', '0.1234567890123456789', '-0.0', '0.0', '-1', '-2.5']) {
  add(['--amount', v, '--currency', 'JPY'], 'B:known');
}

// ---- C: exponent extremes -------------------------------------------------
for (let e = -330; e <= 310; e++) {
  add(['--amount', `1e${e}`, '--currency', 'GBP'], 'C:pow10');
  add(['--amount', `-1.5e${e}`.replace('-', ''), '--currency', 'GBP'], 'C:pow10b');
  add(['--amount', `9.87654321e${e}`, '--currency', 'GBP'], 'C:pow10c');
}
for (const v = 0; false;) { }
for (const v of ['5e-324', '1e-323', '2.5e-324', '4.9e-324', '2.2250738585072014e-308',
  '1.7976931348623157e308', '1.7976931348623158e308', '1e309', '1e400', '1e-400', '2.2e-308',
  '4.450147717014403e-308', '1.1125369292536007e-308']) {
  add(['--amount', v, '--currency', 'CAD'], 'C:extreme');
}

// ---- D: specials ----------------------------------------------------------
for (const v of ['inf', 'Inf', 'INF', 'infinity', 'Infinity', 'INFINITY', 'nan', 'NaN', 'NAN',
  '+inf', '+infinity', '+nan', '-nan', ' inf ', '\tnan\n', 'iNfInItY']) {
  add(['--amount', v, '--currency', 'USD'], 'D:special');
  add([`--amount=${v}`, '--currency', 'USD'], 'D:special=');
  add([`--amount=-${v}`, '--currency', 'USD'], 'D:specialneg');
}

// ---- E: odd-but-maybe-valid float literals --------------------------------
for (const v of ['+5', '.5', '5.', '+.5', '-.5', '1_000', '1_0.5', '1_000_000.000_1', '1__0', '_1',
  '1_', '1._5', '1.5_', '0x10', '0b101', '0o17', '1e', 'e5', '1,5', '', ' ', '  5  ', '\t\n\r 5 \f\v',
  '　5', ' 5', '５', '５．５', '٣', '١٢٣', '۵',
  '०१', '5�', 'None', 'True', '½', '⁵', '1e+5', '1E+5', '1e-5', '1E5', '00005',
  '000.5000', '5e0', '5E0', '+0', '-0', '- 5', '+ 5', '5 5', '1.2.3', '..5', '5..', 'nan(0x1)',
  '1d5', '1f', '5j', '(5)', '"5"', '1e1_0', '1_e5']) {
  add(['--amount', v, '--currency', 'USD'], 'E:lit');
}

// ---- F: argparse edges ----------------------------------------------------
const F = [
  [], ['--amount', '5'], ['--currency', 'USD'], ['--help'], ['-h'], ['--he'], ['--h'],
  ['--amount', '5', '--currency', 'USD', '--help'],
  ['--amount=5', '--currency=USD'], ['--am', '5', '--cur', 'USD'], ['--a', '5', '--c', 'USD'],
  ['--a', '5', '--currency', 'USD'], ['--amoun', '5', '--curr', 'USD'],
  ['--amount', '5', '--currency', 'USD', 'extra'], ['--amount', '5', '--currency', 'USD', '--bogus'],
  ['--amount', '5', '--currency', 'USD', '--bogus', 'x'],
  ['extra', '--amount', '5', '--currency', 'USD'],
  ['--', '--amount', '5', '--currency', 'USD'], ['--amount', '5', '--', '--currency', 'USD'],
  ['--amount', '5', '--currency=USD', '--'], ['--amount', '5', '--currency', 'USD', '--', 'x'],
  ['--amount'], ['--amount', '--currency', 'USD'], ['--amount', '--currency=USD'],
  ['--currency'], ['--currency', '--amount', '5'],
  ['--amount', '5', '--amount', '7', '--currency', 'USD'],
  ['--currency', 'USD', '--currency', 'GBP', '--amount', '5'],
  ['--currency', 'USD', '--amount', '5'],
  ['--AMOUNT', '5', '--currency', 'USD'], ['--Amount', '5', '--currency', 'USD'],
  ['-amount', '5', '--currency', 'USD'], ['-a', '5', '--currency', 'USD'],
  ['--amount', '-5', '--currency', 'USD'], ['--amount', '-5.5', '--currency', 'USD'],
  ['--amount', '-inf', '--currency', 'USD'], ['--amount=-inf', '--currency', 'USD'],
  ['--amount', '-1e400', '--currency', 'USD'], ['--amount=-1e400', '--currency', 'USD'],
  ['--amount', '--5', '--currency', 'USD'], ['--amount', '-.5', '--currency', 'USD'],
  ['--amount=', '--currency', 'USD'], ['--amount=5', '--currency='],
  ['--amount', '5', '--currency', '-USD'], ['--amount', '5', '--currency', '--USD'],
  ['--amount', '5'], ['--amount', '5', '--currenc', 'USD'], ['--amount', '5', '--cu', 'USD'],
  ['--amount', '5', '--currency', 'USD', '-h'],
  ['--amount', 'x', '--currency', 'XYZ'],
  ['--amount', '5', '--currency', 'USD', '--amount'],
  ['--amount=5=6', '--currency', 'USD'],
  ['--amount', '5', '--currency', 'US D'],
];
for (const argv of F) add(argv, 'F:argparse');

// ---- G: currencies -------------------------------------------------------
for (const c of VALID) {
  add(['--amount', '133.13', '--currency', c], 'G:valid');
  add(['--amount', '133.13', '--currency', c.toLowerCase()], 'G:lower');
  add(['--amount', '133.13', '--currency', c[0] + c.slice(1).toLowerCase()], 'G:mixed');
}
const INVALID = readFileSync('/tmp/invalid3.txt', 'utf8').trim().split('\n');
for (let i = 0; i < 500; i++) add(['--amount', '1', '--currency', pick(INVALID)], 'G:invalid3');
for (const c of ['', ' ', 'US', 'USDD', '840', 'usd ', ' usd', 'U S', 'Ω', 'ＵＳＤ', 'usd\n', '0',
  'null', 'None', 'XXXX', 'xxx', 'zwg', 'ZWG', 'xcg', 'XCG', 'btc', 'BTC', 'ETH', 'eur']) {
  add(['--amount', '1', '--currency', c], 'G:invalidmisc');
}

// ---- H: fuzz amount strings ---------------------------------------------
const ALPH = '0123456789+-.eE_ \tinfaNIF,xX';
for (let i = 0; i < 2500; i++) {
  const n = 1 + ri(8);
  let s = '';
  for (let k = 0; k < n; k++) s += ALPH[ri(ALPH.length)];
  add([`--amount=${s}`, '--currency', 'USD'], 'H:fuzz');
}

mkdirSync('/tmp/dt', { recursive: true });
writeFileSync('/tmp/dt/corpus.jsonl', cases.map((c) => JSON.stringify(c)).join('\n') + '\n');
console.log('cases:', cases.length);
const byTag = {};
for (const c of cases) byTag[c.tag] = (byTag[c.tag] || 0) + 1;
console.log(byTag);

