// bignum.mjs -- arbitrary-precision non-negative integers held as arrays of
// decimal digits, most-significant digit first.  Everything here is explicit
// schoolbook long arithmetic over base 10; no wide-integer primitive of any
// kind is used, and no host numeric formatting helper is involved beyond
// plain Number for indices and single digits.
//
// Canonical form: a non-empty array of integers 0..9 with no leading zero,
// except for zero itself which is exactly [0].

/** Strip leading zeros, keeping at least one digit. */
export function normalize(d) {
  let i = 0;
  while (i < d.length - 1 && d[i] === 0) i++;
  return i === 0 ? d : d.slice(i);
}

/** "0123" -> [1,2,3] (canonical). Only ASCII digits are accepted. */
export function fromDigits(s) {
  const out = new Array(s.length);
  for (let i = 0; i < s.length; i++) out[i] = s.charCodeAt(i) - 48;
  if (out.length === 0) return [0];
  return normalize(out);
}

/** [1,2,3] -> "123" */
export function toDigits(d) {
  let s = '';
  for (let i = 0; i < d.length; i++) s += String(d[i]);
  return s;
}

export function isZero(d) {
  for (let i = 0; i < d.length; i++) if (d[i] !== 0) return false;
  return true;
}

/** -1, 0, or 1 for a<b, a==b, a>b. Both must be canonical. */
export function cmp(a, b) {
  if (a.length !== b.length) return a.length < b.length ? -1 : 1;
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return a[i] < b[i] ? -1 : 1;
  }
  return 0;
}

/** a * 10**k  (k >= 0) -- append k zero digits. */
export function mulPow10(a, k) {
  if (isZero(a)) return [0];
  const out = a.slice();
  for (let i = 0; i < k; i++) out.push(0);
  return out;
}

/** a * m for a single digit m (0..9). */
export function mulSmall(a, m) {
  if (m === 0 || isZero(a)) return [0];
  const out = new Array(a.length + 1).fill(0);
  let carry = 0;
  for (let i = a.length - 1; i >= 0; i--) {
    const p = a[i] * m + carry;
    out[i + 1] = p % 10;
    carry = (p - (p % 10)) / 10;
  }
  out[0] = carry;
  return normalize(out);
}

/** Full long multiplication a * b. */
export function mul(a, b) {
  if (isZero(a) || isZero(b)) return [0];
  const out = new Array(a.length + b.length).fill(0);
  for (let i = a.length - 1; i >= 0; i--) {
    let carry = 0;
    const ai = a[i];
    for (let j = b.length - 1; j >= 0; j--) {
      const pos = i + j + 1;
      const t = out[pos] + ai * b[j] + carry;
      out[pos] = t % 10;
      carry = (t - (t % 10)) / 10;
    }
    let pos = i;
    while (carry > 0) {
      const t = out[pos] + carry;
      out[pos] = t % 10;
      carry = (t - (t % 10)) / 10;
      pos--;
    }
  }
  return normalize(out);
}

/** a - b, requires a >= b. */
export function sub(a, b) {
  const out = a.slice();
  let i = out.length - 1;
  let j = b.length - 1;
  let borrow = 0;
  while (i >= 0) {
    let t = out[i] - borrow - (j >= 0 ? b[j] : 0);
    if (t < 0) { t += 10; borrow = 1; } else { borrow = 0; }
    out[i] = t;
    i--; j--;
  }
  return normalize(out);
}

/** a + small (0 <= small <= 9). */
export function addSmall(a, small) {
  const out = a.slice();
  let carry = small;
  for (let i = out.length - 1; i >= 0 && carry > 0; i--) {
    const t = out[i] + carry;
    out[i] = t % 10;
    carry = (t - (t % 10)) / 10;
  }
  if (carry > 0) out.unshift(carry);
  return normalize(out);
}

/**
 * Schoolbook long division: returns [quotient, remainder].
 * The divisor must be non-zero.  The quotient digit at each step is found by
 * comparing the running remainder against small multiples of the divisor,
 * exactly as one would do it on paper.
 */
export function divmod(a, b) {
  if (isZero(b)) throw new Error('divmod by zero');
  if (cmp(a, b) < 0) return [[0], a.slice()];
  const q = new Array(a.length).fill(0);
  let rem = [0];
  for (let i = 0; i < a.length; i++) {
    // rem = rem * 10 + a[i]
    if (isZero(rem)) rem = [a[i]];
    else { rem = rem.slice(); rem.push(a[i]); }
    // largest digit k with b*k <= rem
    let k = 0;
    for (let t = 9; t >= 1; t--) {
      if (cmp(mulSmall(b, t), rem) <= 0) { k = t; break; }
    }
    if (k > 0) rem = sub(rem, mulSmall(b, k));
    q[i] = k;
  }
  return [normalize(q), normalize(rem)];
}

/** a mod m for a small positive m (m <= 10 is all this program needs, but any
 *  m up to 2**26 works). Computed by a linear Horner pass, no division of
 *  the whole number required. */
export function modSmall(a, m) {
  let r = 0;
  for (let i = 0; i < a.length; i++) r = (r * 10 + a[i]) % m;
  return r;
}

/** floor(a / 10) -- drop the least significant digit. */
export function divBy10(a) {
  if (a.length <= 1) return [0];
  return normalize(a.slice(0, a.length - 1));
}

// unicodedata.mjs -- the small slices of the Unicode character database that
// CPython consults on the code paths this program reproduces:
//
//   * Py_UNICODE_ISSPACE   (used by _PyUnicode_TransformDecimalAndSpaceToASCII
//                           and by str.strip())
//   * Py_UNICODE_TODECIMAL (the "decimal digit value" field, category Nd)
//   * Py_UNICODE_ISPRINTABLE (used by unicode_repr / repr(str))

// ---------------------------------------------------------------- whitespace

// ASCII part of _Py_ascii_whitespace: \t \n \v \f \r \x1c \x1d \x1e \x1f space
const ASCII_SPACE = new Set([0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20]);

// Non-ASCII code points for which Py_UNICODE_ISSPACE is true.
const WIDE_SPACE = new Set([
  0x0085, 0x00a0, 0x1680,
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007, 0x2008,
  0x2009, 0x200a, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
]);

export function isPySpace(cp) {
  if (cp < 0x80) return ASCII_SPACE.has(cp);
  return WIDE_SPACE.has(cp);
}

// The subset of Py_ISSPACE (the C ctype table) used by float_from_string_inner
// when it trims the transformed byte string: space \t \n \v \f \r only.
export function isCSpace(ch) {
  return ch === ' ' || ch === '\t' || ch === '\n' || ch === '\v' || ch === '\f' || ch === '\r';
}

// --------------------------------------------------------------- Nd decimals

// Every general-category-Nd block in Unicode is a run of ten consecutive code
// points whose decimal values are 0..9, so the whole table is just the run
// starts.  (A handful of scripts contribute several runs; each is listed.)
const ND_STARTS = [
  0x0030, 0x0660, 0x06f0, 0x07c0, 0x0966, 0x09e6, 0x0a66, 0x0ae6, 0x0b66,
  0x0be6, 0x0c66, 0x0ce6, 0x0d66, 0x0de6, 0x0e50, 0x0ed0, 0x0f20, 0x1040,
  0x1090, 0x17e0, 0x1810, 0x1946, 0x19d0, 0x1a80, 0x1a90, 0x1b50, 0x1bb0,
  0x1c40, 0x1c50, 0xa620, 0xa8d0, 0xa900, 0xa9d0, 0xa9f0, 0xaa50, 0xabf0,
  0xff10,
  0x104a0, 0x10d30, 0x10d40, 0x11066, 0x110f0, 0x11136, 0x111d0, 0x112f0,
  0x11450, 0x114d0, 0x11650, 0x116c0, 0x11730, 0x118e0, 0x11950, 0x11c50,
  0x11d50, 0x11da0, 0x11f50, 0x16a60, 0x16ac0, 0x16b50, 0x16d70, 0x1d7ce,
  0x1d7d8, 0x1d7e2, 0x1d7ec, 0x1d7f6, 0x1e140, 0x1e2f0, 0x1e4f0, 0x1e950,
  0x1fbf0,
];
const ND_SET = new Map();
for (const s of ND_STARTS) for (let k = 0; k < 10; k++) ND_SET.set(s + k, k);

/** Py_UNICODE_TODECIMAL: 0..9, or -1 when the code point has no decimal value. */
export function toDecimalValue(cp) {
  const v = ND_SET.get(cp);
  return v === undefined ? -1 : v;
}

// ---------------------------------------------------------------- printable

// Py_UNICODE_ISPRINTABLE is false for categories Cc, Cf, Cs, Co, Cn, Zl, Zp
// and Zs -- except that U+0020 SPACE is explicitly printable.  The ranges
// below cover Cc/Zl/Zp/Zs/Cs/Co exactly and Cf plus the large unassigned
// blocks well enough for every input this program can be handed.
const NONPRINTABLE_RANGES = [
  [0x0000, 0x001f], [0x007f, 0x009f],           // Cc
  [0x00a0, 0x00a0], [0x00ad, 0x00ad],           // Zs, Cf (soft hyphen)
  [0x0600, 0x0605], [0x061c, 0x061c], [0x06dd, 0x06dd], [0x070f, 0x070f],
  [0x0890, 0x0891], [0x08e2, 0x08e2],
  [0x1680, 0x1680], [0x180e, 0x180e],
  [0x2000, 0x200f],                              // Zs + Cf (ZWSP..RLM)
  [0x2028, 0x202e],                              // Zl, Zp, Cf, Zs(202f below)
  [0x202f, 0x202f], [0x205f, 0x205f],
  [0x2060, 0x2064], [0x2065, 0x2065], [0x2066, 0x206f],
  [0x3000, 0x3000],
  [0xd800, 0xf8ff],                              // Cs + Co
  [0xfeff, 0xfeff], [0xfff9, 0xfffb],
  [0xfffe, 0xffff],
  [0x110bd, 0x110bd], [0x110cd, 0x110cd],
  [0x13430, 0x1343f],
  [0x1bca0, 0x1bca3],
  [0x1d173, 0x1d17a],
  [0xe0001, 0xe0001], [0xe0020, 0xe007f],
  [0xf0000, 0x10ffff],                           // Co planes 15 and 16
];

export function isPrintable(cp) {
  if (cp === 0x20) return true;
  for (const [lo, hi] of NONPRINTABLE_RANGES) {
    if (cp >= lo && cp <= hi) return false;
  }
  return true;
}

// pyrepr.mjs -- CPython's unicode_repr() for str objects.  argparse renders the
// offending value with %r when a type conversion fails, and the traceback for
// an unhandled KeyError renders the key with %r, so this has to be exact.

import { isPrintable } from './unicodedata.mjs';

function hexEsc(cp) {
  if (cp <= 0xff) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp <= 0xffff) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

/** repr() of a Python str. */
export function pyReprStr(s) {
