  let hasSingle = false;
  let hasDouble = false;
  for (const ch of s) {
    if (ch === "'") hasSingle = true;
    else if (ch === '"') hasDouble = true;
  }
  const quote = hasSingle && !hasDouble ? '"' : "'";

  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === quote || ch === '\\') { out += '\\' + ch; continue; }
    if (ch === '\t') { out += '\\t'; continue; }
    if (ch === '\n') { out += '\\n'; continue; }
    if (ch === '\r') { out += '\\r'; continue; }
