// pyfloat.mjs -- the two halves of CPython's float <-> str behaviour:
//
//   float(str)  =  PyFloat_FromString
//                    -> _PyUnicode_TransformDecimalAndSpaceToASCII
//                    -> _Py_string_to_number_with_underscores
//                    -> float_from_string_inner
//                         -> PyOS_string_to_double
//                              -> _Py_dg_strtod  (grammar only; the actual
//                                                 correctly-rounded conversion
//                                                 is delegated to the host,
//                                                 which uses the same
//                                                 round-to-nearest-even rule)
//                              -> _Py_parse_inf_or_nan
//
//   str(float)  =  float_repr -> PyOS_double_to_string(v, 'r', 0, Py_DTSF_ADD_DOT_0)
//                    -> format_float_short(mode 0)

import { isPySpace, toDecimalValue, isCSpace } from './unicodedata.mjs';

export class PyValueError extends Error {}

// ---------------------------------------------------------------------------
// _PyUnicode_TransformDecimalAndSpaceToASCII
//
//   for each code point ch:
//       if ch < 127            -> keep verbatim
//       elif Py_UNICODE_ISSPACE-> ' '
//       else decimal = Py_UNICODE_TODECIMAL(ch)
//            if decimal < 0    -> '?'   (guarantees a later parse failure)
//            else              -> '0' + decimal
// ---------------------------------------------------------------------------
export function transformDecimalAndSpaceToASCII(s) {
  let out = '';
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (cp < 127) { out += ch; continue; }
    if (isPySpace(cp)) { out += ' '; continue; }
    const dec = toDecimalValue(cp);
    out += dec < 0 ? '?' : String(dec);
  }
  return out;
}

// ---------------------------------------------------------------------------
// _Py_string_to_number_with_underscores
//
// Copies the string, dropping '_'.  Every underscore must be immediately
// preceded by an ASCII digit and immediately followed by an ASCII digit.
// ---------------------------------------------------------------------------
function stripUnderscoresOrThrow(s) {
  if (s.length === 0) return s;
  let out = '';
  let prev = '\0';
  const isDigit = (c) => c >= '0' && c <= '9';
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (c === '_') {
      if (!isDigit(prev)) throw new PyValueError('underscore');
    } else {
      out += c;
      if (prev === '_' && !isDigit(c)) throw new PyValueError('underscore');
    }
    prev = c;
  }
  if (prev === '_') throw new PyValueError('underscore');
  return out;
}

// ---------------------------------------------------------------------------
// _Py_dg_strtod's accepted grammar, plus _Py_parse_inf_or_nan.
// ---------------------------------------------------------------------------
const DEC_RE = /^[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?$/;
const INF_NAN_RE = /^[+-]?(?:inf(?:inity)?|nan)$/i;

/**
 * float(s).  Throws PyValueError when Python would raise ValueError.
 * Returns a JS number (which is a C double, same as Python's float).
 */
export function pyFloat(raw) {
  const ascii = transformDecimalAndSpaceToASCII(raw);
  const noUnderscore = stripUnderscoresOrThrow(ascii);

  // float_from_string_inner: strip leading, then trailing, C whitespace.
  let lo = 0;
  let hi = noUnderscore.length;
  while (lo < hi && isCSpace(noUnderscore[lo])) lo++;
  if (lo === hi) throw new PyValueError('empty');
  while (lo < hi - 1 && isCSpace(noUnderscore[hi - 1])) hi--;
  const body = noUnderscore.slice(lo, hi);

  if (INF_NAN_RE.test(body)) {
    const neg = body[0] === '-';
    if (/nan$/i.test(body)) return NaN;
    return neg ? -Infinity : Infinity;
  }
  if (!DEC_RE.test(body)) throw new PyValueError('bad float');
  // The host conversion is IEEE-754 correctly rounded, matching _Py_dg_strtod;
  // overflow yields +/-Infinity and underflow yields a signed zero, which is
  // exactly what CPython keeps (it ignores ERANGE for float()).
  return Number(body);
}

// ---------------------------------------------------------------------------
// format_float_short(v, 'r', 0, Py_DTSF_ADD_DOT_0) -- i.e. repr()/str() of a
// float.  `mode 0` means "shortest string that round-trips".
// ---------------------------------------------------------------------------

/**
 * Split |v| (finite, non-zero) into the shortest round-tripping digit string D
 * and the decimal point position `decpt`, defined by  |v| = 0.D * 10**decpt.
 * This is the (digits, decpt) pair that _Py_dg_dtoa returns for mode 0.
 */
function shortestDigits(av) {
  const es = av.toExponential();          // "d[.ddd]e+k" -- shortest by spec
  const ei = es.indexOf('e');
  const mant = es.slice(0, ei);
  const k = Number(es.slice(ei + 1));
  let D = '';
  for (let i = 0; i < mant.length; i++) {
    const c = mant[i];
    if (c >= '0' && c <= '9') D += c;
  }
  // Trailing zeros never appear in a shortest representation, but strip
  // defensively so decpt/length arithmetic below cannot drift.
  let end = D.length;
  while (end > 1 && D[end - 1] === '0') end--;
  D = D.slice(0, end);
  return { D, decpt: k + 1 };
}

function signedExponent(e) {
  const neg = e < 0;
  const a = neg ? -e : e;
  let s = String(a);
  if (s.length < 2) s = '0' + s;
  return (neg ? '-' : '+') + s;
}

/** str(float) / repr(float). */
export function pyFloatRepr(v) {
  if (v !== v) return 'nan';                      // Python's str(nan) is unsigned
  if (v === Infinity) return 'inf';
  if (v === -Infinity) return '-inf';
  const negative = v < 0 || (v === 0 && 1 / v < 0);
  const av = negative ? -v : v;
  const sign = negative ? '-' : '';
  if (av === 0) return sign + '0.0';              // ADD_DOT_0

  const { D, decpt } = shortestDigits(av);

  // use_exp = (decpt <= -4 || decpt > 16) for the ADD_DOT_0 repr flavour
  if (decpt > -4 && decpt <= 16) {
    if (decpt <= 0) return sign + '0.' + '0'.repeat(-decpt) + D;
    if (decpt >= D.length) return sign + D + '0'.repeat(decpt - D.length) + '.0';
    return sign + D.slice(0, decpt) + '.' + D.slice(decpt);
  }
  const mant = D.length > 1 ? D[0] + '.' + D.slice(1) : D[0];
  return sign + mant + 'e' + signedExponent(decpt - 1);
}

// decimal.mjs -- a transliteration of the parts of CPython's Lib/_pydecimal.py
// that this program exercises: Decimal.__new__ (string form),
// Decimal.__truediv__, Decimal._fix (with ROUND_HALF_EVEN), the rounding
// helpers, and Decimal.__str__ (to-scientific-string).
//
// Coefficients are kept the way _pydecimal keeps them, as a string of decimal
// digits with no sign and no leading zeros ("0" for a zero coefficient).  All
// arithmetic on them goes through ./bignum.mjs.

import * as bn from './bignum.mjs';

// ------------------------------------------------------------- the context
// decimal.DefaultContext, i.e. what getcontext() hands out in a fresh thread.
export const Context = {
  prec: 28,
  rounding: 'ROUND_HALF_EVEN',
  Emax: 999999,
  Emin: -999999,
  capitals: 1,
  clamp: 0,
  Etiny() { return this.Emin - this.prec + 1; },
  Etop() { return this.Emax - this.prec + 1; },
};

// _pydecimal uses the strings 'F', 'n', 'N' in the _exp slot for infinities,
// quiet NaNs and signalling NaNs respectively.
const F = 'F';
const N_QUIET = 'n';
const N_SIGNAL = 'N';

export class Decimal {
  constructor(sign, int_, exp, isSpecial) {
    this._sign = sign;
    this._int = int_;
    this._exp = exp;
    this._is_special = !!isSpecial;
  }

  _isnan() {
    if (!this._is_special) return 0;
    if (this._exp === N_QUIET) return 1;
    if (this._exp === N_SIGNAL) return 2;
    return 0;
  }

  _isinfinity() {
    if (this._exp !== F) return 0;
    return this._sign ? -1 : 1;
  }

  /** Python truthiness: a Decimal is false iff it is a (non-special) zero. */
  _isZero() {
    return !this._is_special && this._int === '0';
  }

  /** _fix_nan: decapitate the payload of a NaN so it fits the context. */
  _fix_nan(context) {
    let payload = this._int;
    const max_payload_len = context.prec - context.clamp;
    if (payload.length > max_payload_len) {
      payload = payload.slice(payload.length - max_payload_len).replace(/^0+/, '');
      return _dec_from_triple(this._sign, payload, this._exp, true);
    }
    return new Decimal(this._sign, this._int, this._exp, this._is_special);
  }

  _check_nans(other, context) {
    const self_is_nan = this._isnan();
    const other_is_nan = other ? other._isnan() : 0;
    if (self_is_nan || other_is_nan) {
      if (self_is_nan === 2) return NAN_RESULT(this._sign);
      if (other_is_nan === 2) return NAN_RESULT(other._sign);
      if (self_is_nan) return this._fix_nan(context);
      return other._fix_nan(context);
    }
    return 0;
  }

  // -------------------------------------------------- Decimal.__truediv__
  __truediv__(other, context) {
    const ctx = context || Context;
    const sign = this._sign ^ other._sign;

    if (this._is_special || other._is_special) {
      const ans = this._check_nans(other, ctx);
      if (ans) return ans;
      if (this._isinfinity() && other._isinfinity()) {
        return NAN_RESULT(0);                       // InvalidOperation
      }
      if (this._isinfinity()) return SIGNED_INFINITY(sign);
      if (other._isinfinity()) {
        // Clamped: zero with the smallest possible exponent
        return _dec_from_triple(sign, '0', ctx.Etiny());
      }
    }

    // Special cases for zeroes
    if (other._isZero()) {
      if (this._isZero()) return NAN_RESULT(0);     // DivisionUndefined 0/0
      return SIGNED_INFINITY(sign);                 // DivisionByZero
    }

    let coeff;                                      // digit array
    let exp;
    if (this._isZero()) {
      exp = this._exp - other._exp;
      coeff = [0];
    } else {
      // OK, so neither is 0, INF or NaN
      const shift = other._int.length - this._int.length + ctx.prec + 1;
      exp = this._exp - other._exp - shift;
      const op1 = bn.fromDigits(this._int);
      const op2 = bn.fromDigits(other._int);
      let remainder;
      if (shift >= 0) {
        [coeff, remainder] = bn.divmod(bn.mulPow10(op1, shift), op2);
      } else {
        [coeff, remainder] = bn.divmod(op1, bn.mulPow10(op2, -shift));
      }
      if (!bn.isZero(remainder)) {
        // result is not exact; adjust to ensure correct rounding
        if (bn.modSmall(coeff, 5) === 0) coeff = bn.addSmall(coeff, 1);
      } else {
        // result is exact; get as close to the ideal exponent as possible
        const ideal_exp = this._exp - other._exp;
        while (exp < ideal_exp && bn.modSmall(coeff, 10) === 0) {
          coeff = bn.divBy10(coeff);
          exp += 1;
        }
      }
    }
    const ans = _dec_from_triple(sign, bn.toDigits(coeff), exp);
    return ans._fix(ctx);
  }

  // ------------------------------------------------------- Decimal._fix
  _fix(context) {
    if (this._is_special) {
      if (this._isnan()) return this._fix_nan(context);
      return this;                                  // infinity: unchanged
    }
    const Etiny = context.Etiny();
    const Etop = context.Etop();

    if (this._isZero()) {
      const exp_max = context.clamp ? Etop : context.Emax;
      let new_exp = this._exp;
      if (new_exp < Etiny) new_exp = Etiny;
      if (new_exp > exp_max) new_exp = exp_max;
      if (new_exp !== this._exp) return _dec_from_triple(this._sign, '0', new_exp);
      return this;
    }

    let exp_min = this._int.length + this._exp - context.prec;
    if (exp_min > Etop) {
      // overflow: exp_min > Etop iff self.adjusted() > Emax
      return SIGNED_INFINITY(this._sign);           // Overflow, ROUND_HALF_EVEN
    }
    const self_is_subnormal = exp_min < Etiny;
    if (self_is_subnormal) exp_min = Etiny;

    // round if self has too many digits
    if (this._exp < exp_min) {
      let self_ = this;
      let digits = this._int.length + this._exp - exp_min;
      if (digits < 0) {
        self_ = _dec_from_triple(this._sign, '1', exp_min - 1);
        digits = 0;
      }
      const changed = _round_half_even(self_, digits);
      let coeff = self_._int.slice(0, digits) || '0';
      if (changed > 0) {
        coeff = bn.toDigits(bn.addSmall(bn.fromDigits(coeff), 1));
        if (coeff.length > context.prec) {
          coeff = coeff.slice(0, coeff.length - 1);
          exp_min += 1;
        }
      }
      if (exp_min > Etop) return SIGNED_INFINITY(this._sign);
      return _dec_from_triple(this._sign, coeff, exp_min);
    }

    // fold down if clamp == 1 and self has too few digits
    if (context.clamp === 1 && this._exp > Etop) {
      const padded = this._int + '0'.repeat(this._exp - Etop);
      return _dec_from_triple(this._sign, padded, Etop);
    }
    // here self was representable to begin with; return unchanged
    return this;
  }

  // -------------------------------------------- Decimal.__str__ (to-sci-string)
  toString(eng, context) {
    const ctx = context || Context;
    const sign = this._sign ? '-' : '';

    if (this._is_special) {
      if (this._exp === F) return sign + 'Infinity';
      if (this._exp === N_QUIET) return sign + 'NaN' + this._int;
      return sign + 'sNaN' + this._int;
    }

    // number of digits of self._int to left of decimal point
    const leftdigits = this._exp + this._int.length;

    // dotplace is number of digits of self._int to the left of the
    // decimal point in the mantissa of the output string (that is,
    // after adjusting the exponent)
    let dotplace;
    if (this._exp <= 0 && leftdigits > -6) {
      // no exponent required
      dotplace = leftdigits;
    } else if (!eng) {
      // usual scientific notation: 1 digit on left of the point
      dotplace = 1;
    } else if (this._int === '0') {
      // engineering notation, zero
      dotplace = ((leftdigits + 1) % 3) - 1 + 1;
      if (dotplace > leftdigits) dotplace -= 3;
    } else {
      // engineering notation, nonzero
      dotplace = ((leftdigits - 1) % 3) + 1;
    }

    let intpart;
    let fracpart;
    if (dotplace <= 0) {
      intpart = '0';
      fracpart = '.' + '0'.repeat(-dotplace) + this._int;
    } else if (dotplace >= this._int.length) {
      intpart = this._int + '0'.repeat(dotplace - this._int.length);
      fracpart = '';
    } else {
      intpart = this._int.slice(0, dotplace);
      fracpart = '.' + this._int.slice(dotplace);
    }

    let exp;
    if (leftdigits === dotplace) {
      exp = '';
    } else {
      const e = leftdigits - dotplace;
      exp = (ctx.capitals ? 'E' : 'e') + (e >= 0 ? '+' : '-') + String(e < 0 ? -e : e);
    }
    return sign + intpart + fracpart + exp;
  }
}

// _dec_from_triple
export function _dec_from_triple(sign, coefficient, exponent, special) {
  return new Decimal(sign, coefficient, exponent, special);
}

function SIGNED_INFINITY(sign) {
  return new Decimal(sign, '0', F, true);
}
function NAN_RESULT(sign) {
  // InvalidOperation under the default (non-trapping for these flags in this
  // program's usage) handling yields a quiet NaN with no payload.
  return new Decimal(sign ? 0 : 0, '', N_QUIET, true);
}

// -------------------------------------------------------- rounding helpers
// _pydecimal's module-level helpers, verbatim in behaviour.
function _all_zeros(coeff, precision) {
  for (let i = precision; i < coeff.length; i++) if (coeff[i] !== '0') return false;
  return true;
}

function _exact_half(coeff, precision) {
  if (coeff[precision] !== '5') return false;
  for (let i = precision + 1; i < coeff.length; i++) if (coeff[i] !== '0') return false;
  return true;
}

/** Decimal._round_half_up: 1 = round away from zero, 0 = exact, -1 = truncate. */
function _round_half_up(d, prec) {
  const c = d._int[prec];
  if (c === '5' || c === '6' || c === '7' || c === '8' || c === '9') return 1;
  if (_all_zeros(d._int, prec)) return 0;
  return -1;
}

/** Decimal._round_half_even. */
function _round_half_even(d, prec) {
  if (_exact_half(d._int, prec)) {
    if (prec === 0) return -1;
    const c = d._int[prec - 1];
    if (c === '0' || c === '2' || c === '4' || c === '6' || c === '8') return -1;
  }
  return _round_half_up(d, prec);
}

// ------------------------------------------------- Decimal.__new__ (str form)
// _pydecimal._parser, in VERBOSE|IGNORECASE form.
const PARSER = new RegExp(
  '^(?<sign>[-+])?(?:' +
  '(?=[0-9]|\\.[0-9])(?<int>[0-9]*)(?:\\.(?<frac>[0-9]*))?(?:E(?<exp>[-+]?[0-9]+))?' +
  '|Inf(?:inity)?' +
  '|(?<signal>s)?NaN(?<diag>[0-9]*)' +
  ')$',
  'i',
);

export class DecimalConversionError extends Error {}

/** Decimal(value) for a str value. */
export function decimalFromString(value) {
  const m = PARSER.exec(value.trim().replace(/_/g, ''));
  if (m === null) throw new DecimalConversionError('Invalid literal for Decimal: ' + value);
  const g = m.groups;
  const sign = g.sign === '-' ? 1 : 0;
  if (g.int !== undefined && g.int !== null) {
    const intpart = g.int;
    const fracpart = g.frac === undefined || g.frac === null ? '' : g.frac;
    const exp = g.exp === undefined || g.exp === null ? 0 : Number(g.exp);
    // self._int = str(int(intpart+fracpart)) -- drops leading zeros
    let digits = (intpart + fracpart).replace(/^0+/, '');
    if (digits === '') digits = '0';
    return new Decimal(sign, digits, exp - fracpart.length, false);
  }
  const diag = g.diag;
  if (diag !== undefined && diag !== null) {
    // NaN: the payload keeps its leading zeros stripped
    const payload = diag.replace(/^0+/, '');
    return new Decimal(sign, payload, g.signal ? N_SIGNAL : N_QUIET, true);
  }
  return new Decimal(sign, '0', F, true);
}

/** Decimal(intValue) for a small non-negative int literal, e.g. Decimal(2). */
export function decimalFromInt(n) {
  const neg = n < 0;
  return new Decimal(neg ? 1 : 0, String(neg ? -n : n), 0, false);
}

