 * Print the chained traceback for the CurrencyDoesNotExist raised out of
 * get_currency(), then the PyInstaller failure notice.  stdout is untouched.
 */
export function printUnhandledCurrencyError(keyRepr, message) {
  const parts = [];
  for (const l of LINES_KEYERROR) parts.push(l);
  parts.push('KeyError: ' + keyRepr);
  for (const l of LINES_MAIN) parts.push(l);
  parts.push('moneyed.classes.CurrencyDoesNotExist: ' + message);
  parts.push(`[PYI-${process.pid}:ERROR] Failed to execute script 'test6' due to unhandled exception!`);
  process.stderr.write(parts.join('\n') + '\n');
