import { CURRENCIES } from './currencies.mjs';
import { Decimal, decimalFromString, decimalFromInt } from './decimal.mjs';
import { pyFloatRepr } from './pyfloat.mjs';

export class KeyError extends Error {
  constructor(key) { super(key); this.key = key; }
}

export class CurrencyDoesNotExist extends Error {
  constructor(code) {
    super(`No currency with code ${code} is defined.`);
    this.code = code;
  }
}

/**
 * moneyed.classes.get_currency:
 *     try:
 *         return CURRENCIES[code]      # line 400
 *     except KeyError:
 *         raise CurrencyDoesNotExist(code)   # line 402
 */
export function getCurrency(code) {
  if (!CURRENCIES.has(code)) {
    const inner = new KeyError(code);
    const outer = new CurrencyDoesNotExist(code);
    outer.cause = inner;
    throw outer;
  }
  return code;
}

export class Money {
  /**
   * Money.__init__:
   *     if not isinstance(amount, Decimal):
   *         amount = Decimal(str(amount))
