function _get_action_name(argument) {
  if (argument === null || argument === undefined) return null;
  if (argument.option_strings && argument.option_strings.length) {
    return argument.option_strings.join('/');
  }
  if (argument.metavar !== null && argument.metavar !== undefined) return argument.metavar;
  if (argument.dest !== null && argument.dest !== undefined) return argument.dest;
  return null;
}

// argparse's _negative_number_matcher.  Python's `\d` is Unicode-aware, hence
// the \p{Nd} class here rather than an ASCII-only \d.
const NEGATIVE_NUMBER_MATCHER = /^-[\p{Nd}]+$|^-[\p{Nd}]*\.[\p{Nd}]+$/u;

export class ArgumentParser {
  constructor(prog) {
    this.prog = prog;
    this.prefix_chars = '-';
    this._actions = [];
    this._option_string_actions = new Map();
    this._has_negative_number_optionals = false;
    // add_help=True installs -h/--help first, exactly as ArgumentParser does.
    this.add_argument(['-h', '--help'], {
      dest: 'help', nargs: 0, kind: 'help',
      help: 'show this help message and exit',
    });
  }

  add_argument(option_strings, kwargs) {
    const action = {
      option_strings,
      dest: kwargs.dest,
      nargs: kwargs.nargs === undefined ? null : kwargs.nargs,
      type: kwargs.type === undefined ? null : kwargs.type,
      required: !!kwargs.required,
      help: kwargs.help === undefined ? null : kwargs.help,
      metavar: kwargs.metavar === undefined ? null : kwargs.metavar,
      kind: kwargs.kind || 'store',
      default: null,
    };
    this._actions.push(action);
    for (const os of option_strings) this._option_string_actions.set(os, action);
    return action;
  }

  // ------------------------------------------------------------- formatting
  _get_default_metavar_for_optional(action) {
    return action.dest.toUpperCase();
  }

  _format_args(action) {
    // nargs=None -> '%s' % get_metavar(1)
    return action.metavar !== null
      ? action.metavar
      : this._get_default_metavar_for_optional(action);
  }

  _format_action_invocation(action) {
    const parts = [];
    if (action.nargs === 0) {
      for (const os of action.option_strings) parts.push(os);
    } else {
      const args_string = this._format_args(action);
      for (const os of action.option_strings) parts.push(os + ' ' + args_string);
    }
    return parts.join(', ');
  }

  _format_action_usage(action) {
    // required optional -> "--amount AMOUNT"; not required -> "[-h]"
    const os = action.option_strings[0];
    if (action.nargs === 0) {
      return action.required ? os : '[' + os + ']';
    }
    const inner = os + ' ' + this._format_args(action);
    return action.required ? inner : '[' + inner + ']';
  }

  format_usage() {
    const parts = this._actions.map((a) => this._format_action_usage(a));
    return 'usage: ' + [this.prog, ...parts].join(' ') + '\n';
  }

  format_help() {
    // HelpFormatter.add_argument: action_max_length = max(len(invocation)) + indent
    const CURRENT_INDENT = 2;
    const MAX_HELP_POSITION = 24;
    let action_max_length = 0;
    for (const a of this._actions) {
      const len = this._format_action_invocation(a).length + CURRENT_INDENT;
      if (len > action_max_length) action_max_length = len;
    }
    const help_position = Math.min(action_max_length + 2, MAX_HELP_POSITION);
    const action_width = help_position - CURRENT_INDENT - 2;

    let out = this.format_usage() + '\n' + 'options:\n';
    for (const a of this._actions) {
      const header = this._format_action_invocation(a);
      if (!a.help) {
        out += ' '.repeat(CURRENT_INDENT) + header + '\n';
      } else if (header.length <= action_width) {
        out += ' '.repeat(CURRENT_INDENT) + header.padEnd(action_width) + '  ' + a.help + '\n';
      } else {
        out += ' '.repeat(CURRENT_INDENT) + header + '\n';
        out += ' '.repeat(help_position) + a.help + '\n';
      }
    }
    return out;
  }

  // ------------------------------------------------------------ error paths
  exit(status, message) {
    throw new SystemExit(status, message);
  }

  error(message) {
    // ArgumentParser.error: print_usage(stderr) then exit(2, ...)
    this.exit(2, this.format_usage() + `${this.prog}: error: ${message}\n`);
  }

  // ------------------------------------------------------------- the parser
  parse_args(args) {
    const [namespace, argv] = this.parse_known_args(args);
    if (argv.length) {
      this.error('unrecognized arguments: ' + argv.join(' '));
    }
    return namespace;
  }

  parse_known_args(args) {
    const namespace = Object.create(null);
    for (const action of this._actions) {
      if (action.dest !== 'help') namespace[action.dest] = action.default;
    }
    try {
      return this._parse_known_args(args, namespace);
    } catch (e) {
      if (e instanceof ArgumentError) {
        this.error(e.str());
      }
      throw e;
    }
  }

  _parse_known_args(arg_strings, namespace) {
    const self = this;

    // ---- classify every argument as an optional ('O'), a positional-ish
    //      value ('A') or the bare '--' separator ('-').
    const option_string_indices = new Map();
    const arg_strings_pattern_parts = [];
    let afterDoubleDash = false;
    for (let i = 0; i < arg_strings.length; i++) {
      const arg_string = arg_strings[i];
      if (!afterDoubleDash && arg_string === '--') {
        arg_strings_pattern_parts.push('-');
        afterDoubleDash = true;
        continue;
      }
      if (afterDoubleDash) {
        arg_strings_pattern_parts.push('A');
        continue;
      }
      const option_tuple = this._parse_optional(arg_string);
      if (option_tuple === null) {
        arg_strings_pattern_parts.push('A');
      } else {
        option_string_indices.set(i, option_tuple);
        arg_strings_pattern_parts.push('O');
      }
    }
    const arg_strings_pattern = arg_strings_pattern_parts.join('');

    const seen_actions = new Set();
    const extras = [];

    function take_action(action, argument_strings, option_string) {
      seen_actions.add(action);
      const argument_values = self._get_values(action, argument_strings);
      if (action.kind === 'help') {
        // _HelpAction.__call__: print help and exit immediately
        process.stdout.write(self.format_help());
        self.exit(0, null);
      }
      namespace[action.dest] = argument_values;
    }

    function consume_optional(start_index) {
      const option_tuple = option_string_indices.get(start_index);
      let [action, option_string, explicit_arg] = option_tuple;
      const action_tuples = [];
      let stop;
      for (;;) {
        if (action === null) {
          extras.push(arg_strings[start_index]);
          return start_index + 1;
        }
        if (explicit_arg !== null && explicit_arg !== undefined) {
          const arg_count = self._match_argument(action, 'A');
          const chars = self.prefix_chars;
          if (arg_count === 0 && !chars.includes(option_string[1]) && explicit_arg !== '') {
            action_tuples.push([action, [], option_string]);
            const char = option_string[0];
            option_string = char + explicit_arg[0];
            const new_explicit_arg = explicit_arg.slice(1) || null;
            if (self._option_string_actions.has(option_string)) {
              action = self._option_string_actions.get(option_string);
              explicit_arg = new_explicit_arg;
            } else {
              throw new ArgumentError(action, `ignored explicit argument ${pyReprStr(explicit_arg)}`);
            }
          } else if (arg_count === 1) {
            stop = start_index + 1;
            action_tuples.push([action, [explicit_arg], option_string]);
            break;
          } else {
            throw new ArgumentError(action, `ignored explicit argument ${pyReprStr(explicit_arg)}`);
          }
        } else {
          const start = start_index + 1;
          const selected_patterns = arg_strings_pattern.slice(start);
          const arg_count = self._match_argument(action, selected_patterns);
          stop = start + arg_count;
          action_tuples.push([action, arg_strings.slice(start, stop), option_string]);
          break;
        }
      }
      for (const [a, args, os] of action_tuples) take_action(a, args, os);
      return stop;
    }

    // No positionals are declared, so consume_positionals always matches the
    // empty pattern and returns start_index unchanged.
    function consume_positionals(start_index) {
      return start_index;
    }

    let start_index = 0;
    const optionIndices = [...option_string_indices.keys()];
    const max_option_string_index = optionIndices.length
      ? Math.max(...optionIndices)
      : -1;
    while (start_index <= max_option_string_index) {
      // consume any Positionals preceding the next option
      let next_option_string_index = -1;
      for (const idx of optionIndices) {
        if (idx >= start_index && (next_option_string_index === -1 || idx < next_option_string_index)) {
          next_option_string_index = idx;
        }
      }
      if (next_option_string_index === -1) break;
      if (start_index !== next_option_string_index) {
        const positionals_end_index = consume_positionals(start_index);
        if (positionals_end_index > start_index) {
          start_index = positionals_end_index;
          continue;
        } else {
          start_index = positionals_end_index;
        }
        if (start_index !== next_option_string_index) {
          for (const s of arg_strings.slice(start_index, next_option_string_index)) extras.push(s);
          start_index = next_option_string_index;
        }
      }
      start_index = consume_optional(next_option_string_index);
    }

    const stop_index = consume_positionals(start_index);
    if (stop_index !== arg_strings.length) {
      for (const s of arg_strings.slice(stop_index)) extras.push(s);
    }

    // required actions that were never seen
    const required_actions = [];
    for (const action of this._actions) {
      if (!seen_actions.has(action) && action.required) {
        required_actions.push(_get_action_name(action));
      }
    }
    if (required_actions.length) {
      this.error('the following arguments are required: ' + required_actions.join(', '));
    }

    return [namespace, extras];
  }

  // _get_nargs_pattern for nargs=None is '(-*A-*)', and for an optional the
  // '-' pieces are stripped, leaving '(A)'; for nargs=0 it leaves '()'.
  _match_argument(action, arg_strings_pattern) {
    const nargs = action.nargs;
    let matched;
    if (nargs === 0) {
      matched = 0;
    } else if (nargs === null) {
      matched = arg_strings_pattern[0] === 'A' ? 1 : -1;
    } else {
      matched = -1;
    }
    if (matched < 0) {
      throw new ArgumentError(action, 'expected one argument');
    }
    return matched;
  }

  _parse_optional(arg_string) {
    // if it's an empty string, it was meant to be a positional
    if (!arg_string) return null;
    // if it doesn't start with a prefix, it was meant to be positional
    if (!this.prefix_chars.includes(arg_string[0])) return null;
    // if the option string is present in the parser, return the action
    if (this._option_string_actions.has(arg_string)) {
      return [this._option_string_actions.get(arg_string), arg_string, null];
    }
    // if it's just a single character, it was meant to be positional
    if (arg_string.length === 1) return null;
    // if the option string before the "=" is present, return the action
    const eq = arg_string.indexOf('=');
    if (eq >= 0) {
      const option_string = arg_string.slice(0, eq);
      const explicit_arg = arg_string.slice(eq + 1);
      if (this._option_string_actions.has(option_string)) {
        return [this._option_string_actions.get(option_string), option_string, explicit_arg];
      }
    }
    // search through all possible prefixes of the option string
    const option_tuples = this._get_option_tuples(arg_string);
    if (option_tuples.length > 1) {
      const options = option_tuples.map((t) => t[1]).join(', ');
      this.error(`ambiguous option: ${arg_string} could match ${options}`);
    } else if (option_tuples.length === 1) {
      return option_tuples[0];
    }
    // if it looks like a negative number, it was meant to be positional
    if (NEGATIVE_NUMBER_MATCHER.test(arg_string)) {
      if (!this._has_negative_number_optionals) return null;
    }
    // if it contains a space, it was meant to be a positional
    if (arg_string.includes(' ')) return null;
    // an unknown option
    return [null, arg_string, null];
  }

  _get_option_tuples(option_string) {
    const result = [];
    const chars = this.prefix_chars;
    if (chars.includes(option_string[0]) && chars.includes(option_string[1])) {
      // long flag: --xxx[=yyy]
      let option_prefix = option_string;
      let explicit_arg = null;
      const eq = option_string.indexOf('=');
      if (eq >= 0) {
        option_prefix = option_string.slice(0, eq);
        explicit_arg = option_string.slice(eq + 1);
      }
      for (const os of this._option_string_actions.keys()) {
        if (os.startsWith(option_prefix)) {
          result.push([this._option_string_actions.get(os), os, explicit_arg]);
        }
      }
    } else if (chars.includes(option_string[0]) && !chars.includes(option_string[1])) {
      // single-dash flag, possibly with its argument glued on
      const option_prefix = option_string;
      const short_option_prefix = option_string.slice(0, 2);
      const short_explicit_arg = option_string.slice(2);
      for (const os of this._option_string_actions.keys()) {
        if (os === short_option_prefix) {
          result.push([this._option_string_actions.get(os), os, short_explicit_arg]);
        } else if (os.startsWith(option_prefix)) {
          result.push([this._option_string_actions.get(os), os, null]);
        }
      }
    }
    return result;
  }

  _get_values(action, arg_strings) {
    // for everything but PARSER/REMAINDER, strip out the first '--'
    const stripped = arg_strings.slice();
    const dd = stripped.indexOf('--');
    if (dd >= 0) stripped.splice(dd, 1);
    if (action.nargs === 0) return null;
    if (stripped.length === 1) return this._get_value(action, stripped[0]);
    return stripped.map((s) => this._get_value(action, s));
  }

  _get_value(action, arg_string) {
    if (action.type === null || action.type === 'str') return arg_string;
    if (action.type === 'float') {
      try {
        return pyFloat(arg_string);
      } catch (e) {
        if (e instanceof PyValueError) {
          throw new ArgumentError(action, `invalid float value: ${pyReprStr(arg_string)}`);
        }
        throw e;
      }
    }
    throw new Error('unsupported type');
  }
}

// test6.mjs -- entry point.  Mirrors:
//
//     import argparse
//     from moneyed import Money
//
//     parser = argparse.ArgumentParser()
//     parser.add_argument('--amount', type=float, required=True)
//     parser.add_argument('--currency', type=str, required=True)
//     args = parser.parse_args()
//
//     m = Money(args.amount, args.currency)   # line 10
//     halved = m / 2
//     print(halved.amount)

import { ArgumentParser, SystemExit } from './lib/argparse.mjs';
import { Money, CurrencyDoesNotExist } from './lib/money.mjs';
import { printUnhandledCurrencyError } from './lib/pyerror.mjs';
import { pyReprStr } from './lib/pyrepr.mjs';

/** os.path.basename(sys.argv[0]) -- argparse's default `prog`. */
function basename(p) {
  const i = p.lastIndexOf('/');
  return i < 0 ? p : p.slice(i + 1);
}

/**
 * The reference implementation is the frozen single-file build of test6.py, so
 * its sys.argv[0] basename -- and therefore argparse's prog, which appears in
 * the usage line on stdout -- is `test6_executable`.  When this port is invoked
 * under its own name we report the same prog so the two programs are
 * byte-identical; a renamed copy falls back to its own basename.
 */
const REFERENCE_PROG = 'test6_executable';
function programName() {
  const base = basename(process.argv[1] || REFERENCE_PROG);
  return base === 'test6.mjs' || base === 'test6' ? REFERENCE_PROG : base;
}

function main() {
  const parser = new ArgumentParser(programName());
  parser.add_argument(['--amount'], { dest: 'amount', type: 'float', required: true });
  parser.add_argument(['--currency'], { dest: 'currency', type: 'str', required: true });
  const args = parser.parse_args(process.argv.slice(2));

  const m = new Money(args.amount, args.currency);
  const halved = m.divideByNumber(2);
  process.stdout.write(halved.amount.toString() + '\n');
}

try {
  main();
} catch (e) {
  if (e instanceof SystemExit) {
    if (e.pymessage) process.stderr.write(e.pymessage);
    process.exitCode = e.code;
  } else if (e instanceof CurrencyDoesNotExist) {
    printUnhandledCurrencyError(pyReprStr(e.code), e.message);
    process.exitCode = 1;
  } else {
    throw e;
  }
}

